/**
 * galleryFigures — the free faces after the first two (doc 180 §12): Claire,
 * Amara, Kofi, Mei and Kenji, and the animals (§17): a kitten, a German shepherd,
 * a labrador, a bear and a lion, the same rig on an animal's face,
 * measured by hand since the face landmarker reads only human faces. Each portrait was generated by the OS's image model,
 * aligned by scripts/portrait-density-map.py, and its landmarks read by
 * MediaPipe on the aligned photo, then corrected by hand where the reading
 * cannot know: the neck (long hair beside it widens the measure), the hair's
 * motion (straight long hair swings less than curls), the eye openings and
 * lashes (sized like the woman's, which cover the white when the lids close),
 * and the cheeks (where a smile lifts, inside the outer cheek points).
 *
 * @module avatar/galleryFigures
 */
import { createPortraitFigure, type PortraitSpec } from './portraitFigure';
// The maps are fetched when a face is worn (portraitMaps); the spec reads its own there.
import { portraitMap } from './portraitMaps';


/** A woman's lashes, a little shorter than the first woman's. */
const LASHES_W = { count: 13, long: 19, short: 6 };
const LASHES_M = { count: 11, long: 12, short: 4 };

