/** An animal without brows: the fur above its eyes lifts with them, along this line. */
const furBrows = (y: number): PortraitSpec['brows'] => [
  [[222, y], [202, y - 6], [182, y - 8], [162, y - 6], [146, y]],
  [[290, y], [310, y - 6], [330, y - 8], [350, y - 6], [366, y]],
];
/** Animals have no hair of their own here: their fur is skin, the head moves as one. */
const NO_HAIR = { cx: 256, cy: 200, rx: 230, ry: 200, depth: 0.62, still: 1.1, sway: 0.08 };
const NO_LASHES = { count: 0, long: 0, short: 0 };

